const SOLO_TASKS = [
  { id:"instagram", label:"Instagram Story",     desc:"Post a story on Instagram mentioning @unmarked.au — upload your screenshot", pin:"8888", points:2, icon:"📱", hasUpload:true },
  { id:"favcar",    label:"Favourite Car Photo", desc:"Take a photo of your favourite car — counts towards awards",                 pin:"8888", points:2, icon:"⭐", hasUpload:true },
];

const REQUIRED = 5;
const REDEEM_PIN = "8008";

function totalPts(vendorStamps, soloCompleted) {
  let p = 0;
  VENDOR_CATEGORIES.forEach(cat => cat.vendors.forEach(v => { if(vendorStamps[v.id]) p += v.points; }));
  soloCompleted.forEach(id => { const t = SOLO_TASKS.find(t=>t.id===id); if(t) p += t.points; });
  return p;
}
function totalDone(vendorStamps, soloCompleted) { return Object.keys(vendorStamps).length + soloCompleted.length; }
function getInitials(name) {
  return name.trim().split(/\s+/).map(w=>w[0].toUpperCase()).join("").slice(0,3);
}

