// ─── MAIN APP ─────────────────────────────────────────────────────────────────
export default function App() {
  const [screen,setScreen]             = useState("splash");
  const [tab,setTab]                   = useState("passport");
  const [user,setUser]                 = useState(null);
  const [userId,setUserId]             = useState(null);
  const [vendorStamps,setStamps]       = useState({});
  const [soloCompleted,setSolo]        = useState([]);
  const [votes,setVotes]               = useState({});
  const [uploads,setUploads]           = useState({});   // { taskId: dataURL }
  const [bonusPoints,setBonus]         = useState(0);   // points added back after redemption bonus
  const [redeemedPts,setRedeemed]      = useState(0);   // total points spent on prizes
  const [activePin,setActivePin]       = useState(null);
  const [activeCat,setActiveCat]       = useState(null);
  const [lastSuccess,setLast]          = useState(null);
  const [drawDone,setDrawDone]         = useState(false);
  const [leaderboard,setLeaderboard]   = useState([]);

  const rawPoints    = totalPts(vendorStamps, soloCompleted) + bonusPoints;
  const points       = Math.max(0, rawPoints - redeemedPts);
  const currentPrize = getPrize(points);

  // ── Supabase: save registration ──────────────────────────────────────────
  const saveRegistration = useCallback(async (userData) => {
    // Use phone as stable unique ID
    const uid = userData.phone.replace(/\s+/g, "");
    setUserId(uid);

    // Check if they already have progress saved
    try {
      const { data: existing } = await supabase
        .from("entries")
        .select("*")
        .eq("id", uid)
        .single();

      if (existing) {
        // Restore their session
        setStamps(existing.vendor_stamps || {});
        setSolo(existing.solo_completed || []);
        setDrawDone(existing.draw_submitted || false);
        setRedeemed(existing.redeemed_points || 0);
        setUploads(existing.uploads || {});
      }
    } catch(e) { /* no existing entry, fresh start */ }

    // Save registration (upsert so repeat logins don't error)
    try {
      await supabase.from("registrations").upsert({
        phone: userData.phone,
        name: userData.name,
        email: userData.email || null,
        instagram: userData.instagram || null,
      }, { onConflict: "phone" });
    } catch(e) { console.error("Registration save failed", e); }
  }, []);

  // ── Supabase: load leaderboard ────────────────────────────────────────────
  const loadLeaderboard = useCallback(async () => {
    try {
      const { data } = await supabase
        .from("entries")
        .select("*")
        .order("points", { ascending: false })
        .limit(50);
      if(data) setLeaderboard(data.map(e => ({
        id: e.id,
        initials: e.initials,
        name: e.name,
        points: e.points,
        prize: getPrize(e.points),
        submitted: e.draw_submitted,
      })));
    } catch(e) { console.error("Leaderboard load failed", e); }
  }, []);

  useEffect(() => {
    loadLeaderboard();
    const interval = setInterval(loadLeaderboard, 10000);
    return () => clearInterval(interval);
  }, [loadLeaderboard]);

  // ── Supabase: push own entry when points change ───────────────────────────
  useEffect(() => {
    if(!user || !userId || points === 0) return;
    supabase.from("entries").upsert({
      id: userId,
      name: user.name,
      initials: getInitials(user.name),
      points,
      vendor_stamps: vendorStamps,
      solo_completed: soloCompleted,
      draw_submitted: drawDone,
      prize_label: getPrize(points)?.label || null,
      redeemed_points: redeemedPts,
      uploads: uploads,
      updated_at: new Date().toISOString(),
    }).then(({ error }) => { if(error) console.error("Entry save failed", error); });
  }, [user, points, drawDone, userId, vendorStamps, soloCompleted, redeemedPts, uploads]);

  // ── Navigation helpers ────────────────────────────────────────────────────
  const openCat       = cat          => { setActiveCat(cat); setScreen("category"); };
  const openVendorPin = (cat,vendor) => {
    setActivePin({label:vendor.name,icon:cat.icon,pin:vendor.pin,earnedPts:vendor.points,targetId:vendor.id,type:"vendor"});
    setScreen("pin");
  };
  // Upload photo to Supabase Storage — never opens PIN
  const saveUpload = async (taskId, dataUrl) => {
    // Immediately show preview in UI using dataUrl
    setUploads(u => ({...u, [taskId]: dataUrl}));
    // Upload to Supabase Storage in background
    try {
      const base64 = dataUrl.split(",")[1];
      const binary = atob(base64);
      const bytes = new Uint8Array(binary.length);
      for(let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
      const blob = new Blob([bytes], { type: "image/jpeg" });
      const day = new Date().getDay() === 6 ? "saturday" : "sunday";
      const filename = `${day}_${userId || "anon"}_${taskId}_${Date.now()}.jpg`;
      const { data, error } = await supabase.storage
        .from("passport-uploads")
        .upload(filename, blob, { upsert: true });
      if(!error) {
        const { data: urlData } = supabase.storage
          .from("passport-uploads")
          .getPublicUrl(filename);
        const publicUrl = urlData.publicUrl;
        // Store the public URL instead of base64
        const newUploads = {...uploads, [taskId]: publicUrl};
        setUploads(newUploads);
        // Immediately save to entries so admin sees it right away
        if(userId) {
          await supabase.from("entries").upsert({
            id: userId,
            name: user?.name,
            initials: getInitials(user?.name||""),
            points,
            vendor_stamps: vendorStamps,
            solo_completed: soloCompleted,
            draw_submitted: drawDone,
            prize_label: getPrize(points)?.label || null,
            redeemed_points: redeemedPts,
            uploads: newUploads,
            updated_at: new Date().toISOString(),
          });
        }
      }
    } catch(e) { console.error("Upload failed", e); }
  };

  // Open PIN screen — only called when staff verify button is tapped
  const openSoloPin = task => {
    setActivePin({label:task.label,icon:task.icon,pin:task.pin,earnedPts:task.points,targetId:task.id,type:"solo"});
    setScreen("pin");
  };
  const pinSuccess = voteData => {
    if(activePin.type==="vendor") setStamps(s=>({...s,[activePin.targetId]:true}));
    else {
      setSolo(c=>[...c,activePin.targetId]);
      if(voteData) setVotes(v=>({...v,[activePin.targetId]:`${voteData.cat}: ${voteData.pick}`}));
    }
    setLast({label:activePin.label,icon:activePin.icon,earnedPts:activePin.earnedPts});
    setScreen("success");
  };
  const claimSuccess = async () => {
    const prize = getPrize(points);
    if(!prize) return;
    const newRedeemed = redeemedPts + prize.pts;
    setRedeemed(newRedeemed);
    setLast({prizeMode:true, prize});
    // Save immediately to Supabase so refresh doesn't undo it
    if(userId) {
      await supabase.from("entries").upsert({
        id: userId,
        name: user.name,
        initials: getInitials(user.name),
        points: Math.max(0, rawPoints - newRedeemed),
        vendor_stamps: vendorStamps,
        solo_completed: soloCompleted,
        draw_submitted: drawDone,
        prize_label: getPrize(Math.max(0, rawPoints - newRedeemed))?.label || null,
        redeemed_points: newRedeemed,
        uploads: uploads,
        updated_at: new Date().toISOString(),
      });
    }
    setScreen("prizeClaimed");
  };

  const showMainTabs = screen==="main";

  // ── Screens ───────────────────────────────────────────────────────────────
  if(screen==="splash")      return <SplashScreen onEnter={()=>setScreen("register")}/>;
  if(screen==="register")    return <RegisterScreen onRegister={u=>{setUser(u);saveRegistration(u);setScreen("main");}}/>;

  if(screen==="main") return (
    <div style={{position:"relative",minHeight:"100vh",background:BG}}>
      {tab==="passport"   && <PassportTab user={user} points={points} vendorStamps={vendorStamps} soloCompleted={soloCompleted} votes={votes} uploads={uploads} onCat={openCat} onSolo={openSoloPin} onSaveUpload={saveUpload} onSubmitDraw={()=>{setDrawDone(true);setScreen("draw");}} drawSubmitted={drawDone} onClaimPrizes={()=>setScreen("claimPrizes")}/>}
      {tab==="leaderboard" && <LeaderboardTab currentUser={{...user,id:userId}} currentPoints={points} leaderboard={leaderboard}/>}
      {tab==="explore"     && <ExploreTab/>}
      <BottomNav tab={tab} setTab={setTab}/>
    </div>
  );

  if(screen==="category")    return <CategoryScreen cat={activeCat} vendorStamps={vendorStamps} onVendor={openVendorPin} onBack={()=>setScreen("main")}/>;
  if(screen==="pin")         return <PinScreen label={activePin.label} icon={activePin.icon} pin={activePin.pin} hasvote={activePin.hasvote} onSuccess={pinSuccess} onBack={()=>setScreen(activeCat&&activePin?.type==="vendor"?"category":"main")}/>;
  if(screen==="success")     return <SuccessScreen label={lastSuccess.label} icon={lastSuccess.icon} earnedPts={lastSuccess.earnedPts} totalPoints={points} onContinue={()=>setScreen(activeCat&&activePin?.type==="vendor"?"category":"main")}/>;
  if(screen==="claimPrizes") return <ClaimPrizesScreen points={points} onSuccess={claimSuccess} onBack={()=>setScreen("main")}/>;
  if(screen==="prizeClaimed"){
    const prize = getPrize(rawPoints - redeemedPts + (currentPrize?.pts||0) - (currentPrize?.pts||0));
    return <PrizeClaimedScreen prize={currentPrize} remainingPoints={points - (currentPrize?.pts||0)} onContinue={()=>setScreen("main")}/>;
  }
  if(screen==="draw")        return <DrawScreen user={user} points={points} onBack={()=>setScreen("main")}/>;
  return null;
}

